import { test } from 'node:test';
import assert from 'node:assert/strict';
import { join } from 'node:path';
import { parseFile, scan } from '../src/logs.ts';

const fixture = (name: string) => join(import.meta.dirname, 'fixtures', name);

test('Codex cache writes are counted once inside total input', async () => {
  const session = await parseFile('codex', fixture('codex-cache-write.jsonl'));
  assert.equal(session.usage[0].input, 20);
  assert.equal(session.usage[0].cacheWrite, 20);
  const u = session.usage[0];
  assert.equal(u.input + u.cacheRead + u.cacheWrite + u.output, 110);
});

test('Claude replayed assistant IDs count once', async () => {
  const session = await parseFile('claude', fixture('claude-native-replay.jsonl'));
  assert.equal(session.usage.length, 2);
  assert.equal(session.usage.reduce((n, u) => n + u.output, 0), 37363);
  assert.equal(session.nativeID, 'session_3');
});

test('Codex canonical records take precedence over compatibility counters', async () => {
  const session = await parseFile('codex', fixture('codex-compaction-counter-domains.jsonl'));
  assert.equal(session.usage.length, 4);
  assert.equal(session.usage.reduce((n, u) => n + u.output, 0), 6856);
  assert.equal(session.usage[0].input, 785);
  assert.equal(session.usage[0].cacheRead, 213760);
});

test('dsh version selection reads the latest file only', async () => {
  const sessions = await scan([{ source: 'dsh', path: fixture('dsh') }]);
  const session = sessions.find(s => s.nativeID === 'dsh-a');
  assert.ok(session);
  assert.equal(session.title, 'Build script tidy');
  assert.equal(session.usage.length, 2);
  assert.equal(session.usage[0].cacheRead, 1000);
  assert.equal(session.messages.filter(m => m.role === 'user').length, 1);
});

test('dsh compressed logs expose messages and usage', async () => {
  const sessions = await scan([{ source: 'dsh', path: fixture('dsh-skills') }]);
  assert.equal(sessions.length, 3);
  assert.ok(sessions.some(s => s.messages.length > 0));
});
export type Source = 'codex' | 'claude' | 'dsh' | 'desktop' | 'acp';
export type Data = Record<string, unknown>;
export interface Message { id: string; role: string; text: string; time: number; kind: string }
export interface Usage { id: string; time: number; model: string; input: number; output: number; cacheRead: number; cacheWrite: number }
export interface Session {
  id: string; nativeID: string; source: Source; title: string; project: string; home: string;
  created: number; updated: number; parentID?: string; provider?: string; instanceID?: string;
  messages: Message[]; usage: Usage[]; files: string[]; warnings: string[];
  nativeSource?: string;
  nativeStarted?: boolean;
  migration?: { sourceID: string; source: string; sourceNativeID: string; created: number; attachments?: string[] };
}
export interface Location { source: 'codex' | 'claude' | 'dsh'; path: string }
export interface AgentConfig {
  id: string; name: string; kind: 'codex' | 'claude' | 'dsh' | 'acp';
  command: string; args: string[]; env: Record<string, string>; version?: string;
  registryID?: string; installPath?: string; protocol?: number;
}
export const object = (value: unknown): Data => value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Data : {};
export const string = (value: unknown, fallback = ''): string => typeof value === 'string' ? value : fallback;
export const number = (value: unknown): number => typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0;
export function timestamp(value: unknown): number {
  if (typeof value === 'number') return value < 1e11 ? value * 1000 : value;
  const parsed = Date.parse(string(value));
  return Number.isFinite(parsed) ? parsed : 0;
}
export function content(value: unknown): string {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(content).filter(Boolean).join('\n');
  const v = object(value);
  if (typeof v.text === 'string') return v.text;
  if (v.content !== undefined) return content(v.content);
  if (v.type === 'tool_use' || v.type === 'tool_call') return `${string(v.name)}\n${JSON.stringify(v.input ?? v.arguments, null, 2)}`;
  if (Object.keys(v).length) return JSON.stringify(v, null, 2);
  return '';
}
