import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { homedir } from 'node:os';
import { join } from 'node:path';

const titles = new Map<string, string>();
for (const line of (await readFile(join(homedir(), '.codex/session_index.jsonl'), 'utf8')).trim().split('\n')) {
  const record = JSON.parse(line);
  if (typeof record.id === 'string' && typeof record.thread_name === 'string') {
    const title = record.thread_name.trim();
    if (title) titles.set(record.id, title); else titles.delete(record.id);
  }
}
const db = new DatabaseSync(join(homedir(), 'Library/Application Support/Ragdoll/index.sqlite'), { readOnly: true });
try {
  const rows = db.prepare("SELECT native_id, title FROM sessions WHERE source='codex'").all();
  let matched = 0, instructionTitles = 0;
  for (const row of rows) {
    const expected = titles.get(String(row.native_id));
    if (expected) { assert.equal(row.title, expected); matched++; }
    if (/^# AGENTS\.md instructions|^<environment_context>/.test(String(row.title))) instructionTitles++;
  }
  assert.ok(matched > 0);
  console.log(JSON.stringify({ storedSessions: rows.length, matched, instructionTitles }));
  assert.equal(instructionTitles, 0);
} finally { db.close(); }

